/* gs_cal.h — the const flash copies of the READ-ONLY garage-engagement
 * shadow (app/gs_cal.c, GENERATED by tools/gen_gs_cal.py). Shadow-internal:
 * only app/gs_fill.c and the host tests include it. */
#ifndef TCU_APP_GS_CAL_H
#define TCU_APP_GS_CAL_H

#if defined(TCU_OUTPUT_PATH) && !defined(RQF_SHADOW_INSTANCE)
#error "the garage shadow is read-only: an output path may not include gs_cal.h"
#endif

#include <stdint.h>

typedef struct {
    uint32_t addr;
    uint32_t len;
    const uint8_t *data;
} gs_blob_t;

#define GS_NBLOBS   24u
extern const gs_blob_t GS_BLOBS[GS_NBLOBS];

/* a pointer to n bytes at stock flash address a, or 0 */
const uint8_t *gs_cal_lookup(uint32_t a, uint32_t n);

#endif /* TCU_APP_GS_CAL_H */
